  simdjson::dom::parser parser;
  simdjson::dom::element value;
  ASSERT_SUCCESS( parser.parse(pstr).get_object()["key"].get(value) );
  ASSERT_EQUAL( value.is<int64_t>(), true );
  return true;
}

